int main(int argc, char** argv){
  for(int i=1;i<argc;i++){
    const char* s = argv[i];
    // decode escapes \xNN, \t \n \v \f \r \s(space) \0 -> allow arbitrary bytes
    std::string in;
    for(const char* p=s; *p; ){
      if(*p=='\\' && p[1]){
        p++;
        switch(*p){
          case 't': in.push_back('\t'); p++; break;
          case 'n': in.push_back('\n'); p++; break;
          case 'v': in.push_back('\v'); p++; break;
          case 'f': in.push_back('\f'); p++; break;
          case 'r': in.push_back('\r'); p++; break;
          case 's': in.push_back(' '); p++; break;
          case '0': in.push_back('\0'); p++; break;
          case 'x': { p++; int v=0,n=0; while(n<2 && isxdigit((unsigned char)*p)){ int d = (*p<='9')?*p-'0':((*p|32)-'a'+10); v=v*16+d; p++; n++;} in.push_back((char)v); break; }
          default: in.push_back(*p); p++; break;
        }
      } else { in.push_back(*p); p++; }
    }
    const char* what = "OK";
    uint32_t bits = 0;
    try {
      float v = std::stof(in);
      memcpy(&bits, &v, 4);
    } catch (const std::invalid_argument&) { what = "INVALID"; }
      catch (const std::out_of_range&) { what = "RANGE"; }
    printf("%s %08x\n", what, bits);
  }
  return 0;
}
