//! Faithful pure-Rust replication of libstdc++'s `std::stof(const std::string&)`,
//! i.e. glibc `strtof` wrapped by `__gnu_cxx::__stoa`:
//!
//! ```c++
//! errno = 0; float v = strtof(s.c_str(), &end);
//! if (end == s.c_str()) throw std::invalid_argument("stof");
//! if (errno == ERANGE)  throw std::out_of_range("stof");
//! return v;
//! ```
//!
//! Everything below was pinned down by differential testing against the real
//! binary (glibc 2.3x / gcc 12, x86-64, "C" locale, FE_TONEAREST).
//!
//! Notable glibc behaviours replicated here (all discriminating inputs cited):
//!
//! * Underflow ERANGE is *not* simply "result is subnormal": it is
//!   `is_tiny && inexact`.  `"0x1p-149"` and `"0x1p-127"` are exact subnormals
//!   and return fine, while `"1e-45"`, `"1.1754942e-38"` throw out_of_range.
//! * `is_tiny` uses x86 "tininess after rounding": a true value in
//!   `[2^-127, 2^-126)` whose *24-bit* rounding carries up to 2^-126 is not
//!   tiny -> no ERANGE.  `"0x1.ffffffp-127"` -> Ok(0x00800000), whereas the
//!   exact midpoint `1.17549428075736429...e-38` (= 0xffffff*2^-150, exactly
//!   representable in 24 bits, so no carry) -> out_of_range even though it too
//!   rounds up to 2^-126.  Equivalently: tiny <=> correctly-rounded |v| < 2^-126.
//! * The hex path loses one bit of "inexactness" information: glibc overwrites
//!   `round_limb` with the mantissa when shifting into the subnormal range, so
//!   the *first* dropped bit (position L-24 of the significand) is not counted
//!   as inexactness.  Hence `"0x1.000001p-149"` -> Ok(0x00000001) but the
//!   numerically identical decimal 1.40129854784871426...e-45 (=16777217*2^-173)
//!   -> out_of_range, and `"0x1.0000001p-149"` -> out_of_range.
//!   `"0x1.800001p-127"` -> Ok(0x00600000) is the cleanest witness.
//! * Overflow ERANGE <=> the correctly rounded result is infinite.
//!   `"340282356779733661637539395458142568447"` -> Ok(FLT_MAX),
//!   `"...448"` (the exact FLT_MAX/2^128 midpoint, ties-to-even -> inf) -> throws.
//! * `"nan(...)"` payloads are parsed with `strtoull(seq, 0)` and masked to 22
//!   bits: `"nan(123)"` -> 0x7fc0007b, `"nan(0x1)"` -> 0x7fc00001,
//!   `"nan(010)"` -> 0x7fc00008, `"nan(8388607)"` -> 0x7fffffff,
//!   `"nan(4194304)"` -> 0x7fc00000, `"nan(ffffff)"`/`"nan(1x)"`/`"nan(_)"` -> 0x7fc00000.
//!   A payload that overflows u64 leaks its ERANGE into stof:
//!   `"nan(99999999999999999999999)"` throws out_of_range (even
//!   `"nan(99999999999999999999999x)"` does, whose payload is discarded), while
//!   the unterminated `"nan(99999999999999999999999"` consumes only "nan" -> Ok.
//! * `"0x"` / `"0x.p1"` / `"-0xg"` consume only the leading `0` -> Ok(±0.0).
//! * `"1e+"`, `"1.e"`, `"5e-"` -> Ok(1.0)/Ok(1.0)/Ok(5.0) (exponent not consumed);
//!   `"."`, `".e3"`, `"+"`, `""`, `"e3"`, `"- 1"`, `"\xa01"` -> invalid_argument.
//! * Leading whitespace = C-locale isspace = {' ', 0x09..=0x0d} only.

use std::cmp::Ordering;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StofErr {
    /// `std::invalid_argument("stof")`: strtof consumed nothing.
    Invalid,
    /// `std::out_of_range("stof")`: strtof set errno == ERANGE.
    OutOfRange,
}

/// Result of the underlying `strtof` call.
#[derive(Debug, Clone, Copy)]
pub struct StrtofResult {
    pub value: f32,
    /// errno == ERANGE after the call.
    pub erange: bool,
    /// index of `endptr` into the input byte slice.
    pub end: usize,
}

/// `std::stof(s)`.
pub fn stof(s: &str) -> Result<f32, StofErr> {
    stof_bytes(s.as_bytes())
}

/// Same, on raw bytes (`std::string::c_str()` semantics: stops at the first NUL).
pub fn stof_bytes(bytes: &[u8]) -> Result<f32, StofErr> {
    let b = match bytes.iter().position(|&c| c == 0) {
        Some(p) => &bytes[..p],
        None => bytes,
    };
    match strtof(b) {
        None => Err(StofErr::Invalid),
        Some(r) => {
            if r.erange {
                Err(StofErr::OutOfRange)
            } else {
                Ok(r.value)
            }
        }
    }
}

/// Replicates the uncaught-exception path of the C++ program: the exact bytes
/// libstdc++'s verbose terminate handler writes to stderr, then SIGABRT
/// (the shell reports exit status 134).
pub fn stof_or_terminate(s: &str) -> f32 {
    match stof(s) {
        Ok(v) => v,
        Err(e) => {
            let name = match e {
                StofErr::Invalid => "std::invalid_argument",
                StofErr::OutOfRange => "std::out_of_range",
            };
            let msg = format!(
                "terminate called after throwing an instance of '{}'\n  what():  stof\n",
                name
            );
            use std::io::Write;
            let mut err = std::io::stderr();
            let _ = err.write_all(msg.as_bytes());
            let _ = err.flush();
            std::process::abort();
        }
    }
}

// ---------------------------------------------------------------------------
// strtof
// ---------------------------------------------------------------------------

const QNAN_BITS: u32 = 0x7fc0_0000;
const NAN_PAYLOAD_MASK: u64 = 0x003f_ffff;

#[inline]
fn is_c_space(c: u8) -> bool {
    c == b' ' || (0x09..=0x0d).contains(&c)
}

#[inline]
fn lower(c: u8) -> u8 {
    c | 0x20
}

#[inline]
fn hexval(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

#[inline]
fn matches_ci(b: &[u8], i: usize, word: &[u8]) -> bool {
    b.len() >= i + word.len() && (0..word.len()).all(|k| lower(b[i + k]) == word[k])
}

#[inline]
fn signed(bits: u32, neg: bool) -> f32 {
    f32::from_bits(if neg { bits | 0x8000_0000 } else { bits })
}

/// glibc `strtof`.  Returns `None` when no conversion could be performed
/// (endptr == nptr), otherwise the value, the ERANGE flag and endptr.
pub fn strtof(b: &[u8]) -> Option<StrtofResult> {
    let mut i = 0usize;
    while i < b.len() && is_c_space(b[i]) {
        i += 1;
    }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }

    // inf / infinity (case-insensitive)
    if matches_ci(b, i, b"infinity") {
        return Some(StrtofResult { value: signed(0x7f80_0000, neg), erange: false, end: i + 8 });
    }
    if matches_ci(b, i, b"inf") {
        return Some(StrtofResult { value: signed(0x7f80_0000, neg), erange: false, end: i + 3 });
    }
    // nan / nan(n-char-sequence)
    if matches_ci(b, i, b"nan") {
        return Some(parse_nan(b, i + 3, neg));
    }
    // hex
    if i + 1 < b.len() && b[i] == b'0' && lower(b[i + 1]) == b'x' {
        if let Some(r) = parse_hex(b, i + 2, neg) {
            return Some(r);
        }
        // "0x" with no hex digits: only the leading '0' is consumed.
        return Some(StrtofResult { value: signed(0, neg), erange: false, end: i + 1 });
    }
    parse_dec(b, i, neg)
}

// ---------------------------------------------------------------------------
// NaN
// ---------------------------------------------------------------------------

fn parse_nan(b: &[u8], after: usize, neg: bool) -> StrtofResult {
    let mut end = after;
    let mut payload: u64 = 0;
    let mut erange = false;
    if after < b.len() && b[after] == b'(' {
        let start = after + 1;
        let mut k = start;
        while k < b.len() && (b[k].is_ascii_alphanumeric() || b[k] == b'_') {
            k += 1;
        }
        if k < b.len() && b[k] == b')' {
            end = k + 1;
            let (v, consumed, ovf) = strtoull_base0(&b[start..k]);
            if ovf {
                erange = true;
            }
            if consumed == k - start {
                payload = v & NAN_PAYLOAD_MASK;
            }
        }
    }
    StrtofResult {
        value: signed(QNAN_BITS | payload as u32, neg),
        erange,
        end,
    }
}

/// `strtoull(s, &end, 0)` restricted to what an n-char-sequence can contain
/// (ASCII alphanumerics and `_`, no sign, no whitespace).
/// Returns (value, bytes consumed, overflow).
fn strtoull_base0(s: &[u8]) -> (u64, usize, bool) {
    let mut i = 0usize;
    let mut base = 10u64;
    if s.len() >= 1 && s[0] == b'0' {
        if s.len() >= 2 && lower(s[1]) == b'x' && s.len() >= 3 && hexval(s[2]).is_some() {
            base = 16;
            i = 2;
        } else {
            base = 8;
            i = 1; // the leading '0' is itself a valid octal digit
        }
    }
    let start_digits = i;
    let mut acc: u64 = 0;
    let mut ovf = false;
    let mut any = false;
    while i < s.len() {
        let d = match hexval(s[i]) {
            Some(d) if (d as u64) < base => d as u64,
            _ => break,
        };
        any = true;
        match acc.checked_mul(base).and_then(|x| x.checked_add(d)) {
            Some(x) => acc = x,
            None => ovf = true,
        }
        i += 1;
    }
    if !any && base == 8 {
        // just "0": consumed one digit, value 0
        return (0, 1, false);
    }
    if !any {
        return (0, 0, false); // no digits at all -> endptr == nptr
    }
    let _ = start_digits;
    if ovf {
        (u64::MAX, i, true)
    } else {
        (acc, i, false)
    }
}

// ---------------------------------------------------------------------------
// Shared rounding of an exact binary significand
// ---------------------------------------------------------------------------

/// Rounds the value `1.<top24 minus its leading bit> * 2^l` (plus the extra
/// information `rbit` = bit l-24, `sticky` = any bit below l-24) to f32,
/// reproducing glibc's `round_and_return`.
///
/// `hex_quirk` selects glibc's hex-path behaviour, where the bit `rbit`
/// is lost when the mantissa is shifted into the subnormal range (it is
/// neither used for the subnormal rounding decision nor for inexactness);
/// the decimal path keeps full information.
///
/// Returns (bits of |value|, erange).
fn round_binary(l: i64, top24: u32, rbit: bool, sticky: bool, hex_quirk: bool) -> (u32, bool) {
    debug_assert!(top24 & 0x0080_0000 != 0);
    if l >= -126 {
        // normal (or overflow)
        let mut m = top24;
        if rbit && (sticky || (m & 1) == 1) {
            m += 1;
        }
        let mut l = l;
        if m == 0x0100_0000 {
            m >>= 1;
            l += 1;
        }
        if l > 127 {
            return (0x7f80_0000, true); // inf, ERANGE
        }
        return ((((l + 127) as u32) << 23) | (m & 0x007f_ffff), false);
    }
    if l < -150 {
        // glibc: exponent < MIN_EXP - 1 - MANT_DIG  ->  ERANGE, return 0
        return (0, true);
    }
    let shift = (-126 - l) as u32; // 1 ..= 24

    // x86 tininess-after-rounding: glibc only applies this for shift == 1,
    // which is also the only case where the 24-bit rounding can carry out of
    // the subnormal range.  The 24-bit rounding here uses the *correct*
    // round/sticky bits even on the hex path.
    let mut is_tiny = true;
    if shift == 1 {
        let mut m24 = top24;
        if rbit && (sticky || (m24 & 1) == 1) {
            m24 += 1;
        }
        if m24 == 0x0100_0000 {
            is_tiny = false;
        }
    }

    // Subnormal rounding.  glibc rebuilds round_limb from the mantissa itself,
    // discarding `rbit` on the hex path (`more_bits` survives).
    let (eff_rbit, eff_sticky) = if hex_quirk { (false, sticky) } else { (rbit, sticky) };
    let q = if shift >= 24 { 0 } else { top24 >> shift };
    let round_bit = (top24 >> (shift - 1)) & 1 == 1;
    let low = top24 & ((1u32 << (shift - 1)) - 1);
    let more = low != 0 || eff_sticky || eff_rbit;
    let mut mant = q;
    if round_bit && (more || (q & 1) == 1) {
        mant += 1;
    }
    let inexact = round_bit || more;
    // `mant == 0x800000` encodes exactly 2^-126, so this works for the
    // rounded-up-to-normal case too.
    (mant, is_tiny && inexact)
}

// ---------------------------------------------------------------------------
// Hex floats
// ---------------------------------------------------------------------------

fn parse_hex(b: &[u8], after_0x: usize, neg: bool) -> Option<StrtofResult> {
    let mut digits: Vec<u8> = Vec::new();
    let mut nfrac: i64 = 0;
    let mut seen_dot = false;
    let mut any = false;
    let mut k = after_0x;
    while k < b.len() {
        if let Some(d) = hexval(b[k]) {
            digits.push(d);
            any = true;
            if seen_dot {
                nfrac += 1;
            }
            k += 1;
        } else if b[k] == b'.' && !seen_dot {
            seen_dot = true;
            k += 1;
        } else {
            break;
        }
    }
    if !any {
        return None;
    }
    let mut end = k;
    let mut pexp: i64 = 0;
    if k < b.len() && lower(b[k]) == b'p' {
        let mut j = k + 1;
        let mut eneg = false;
        if j < b.len() && (b[j] == b'+' || b[j] == b'-') {
            eneg = b[j] == b'-';
            j += 1;
        }
        if j < b.len() && b[j].is_ascii_digit() {
            let mut e: i64 = 0;
            while j < b.len() && b[j].is_ascii_digit() {
                e = e.saturating_mul(10).saturating_add((b[j] - b'0') as i64);
                if e > 1_000_000_000 {
                    e = 1_000_000_000;
                }
                j += 1;
            }
            pexp = if eneg { -e } else { e };
            end = j;
        }
    }

    // value = digits (base 16) * 2^(pexp - 4*nfrac)
    let first_nz = digits.iter().position(|&d| d != 0);
    let first_nz = match first_nz {
        None => {
            return Some(StrtofResult { value: signed(0, neg), erange: false, end });
        }
        Some(p) => p,
    };
    let sig = &digits[first_nz..];
    let lead_zeros = (sig[0].leading_zeros() - 4) as i64; // 0..=3 within the nibble
    let bitlen = 4 * (sig.len() as i64) - lead_zeros;
    let l = bitlen
        .saturating_sub(1)
        .saturating_add(pexp)
        .saturating_sub(4i64.saturating_mul(nfrac));

    // gather the top 64 bits and a sticky flag
    let mut acc: u64 = 0;
    let mut filled: u32 = 0; // nibbles in acc
    let mut sticky = false;
    for (idx, &d) in sig.iter().enumerate() {
        if idx < 16 {
            acc = (acc << 4) | d as u64;
            filled += 1;
        } else if d != 0 {
            sticky = true;
        }
    }
    let accbits = 4 * filled as i64 - lead_zeros; // significant bits held in acc
    let norm = acc << (64 - accbits) as u32; // leading 1 at bit 63
    let top24 = (norm >> 40) as u32;
    let rbit = (norm >> 39) & 1 == 1;
    sticky |= norm & ((1u64 << 39) - 1) != 0;

    let (bits, erange) = if l > 127 {
        (0x7f80_0000, true)
    } else {
        round_binary(l, top24, rbit, sticky, true)
    };
    Some(StrtofResult { value: signed(bits, neg), erange, end })
}

// ---------------------------------------------------------------------------
// Decimal floats
// ---------------------------------------------------------------------------

fn parse_dec(b: &[u8], start: usize, neg: bool) -> Option<StrtofResult> {
    let mut int_digits: Vec<u8> = Vec::new();
    let mut frac_digits: Vec<u8> = Vec::new();
    let mut k = start;
    while k < b.len() && b[k].is_ascii_digit() {
        int_digits.push(b[k] - b'0');
        k += 1;
    }
    if k < b.len() && b[k] == b'.' {
        let save = k;
        k += 1;
        while k < b.len() && b[k].is_ascii_digit() {
            frac_digits.push(b[k] - b'0');
            k += 1;
        }
        if int_digits.is_empty() && frac_digits.is_empty() {
            let _ = save;
            return None; // "." / ".e3"
        }
    }
    if int_digits.is_empty() && frac_digits.is_empty() {
        return None;
    }
    let mut end = k;
    let mut dexp: i64 = 0;
    if k < b.len() && lower(b[k]) == b'e' {
        let mut j = k + 1;
        let mut eneg = false;
        if j < b.len() && (b[j] == b'+' || b[j] == b'-') {
            eneg = b[j] == b'-';
            j += 1;
        }
        if j < b.len() && b[j].is_ascii_digit() {
            let mut e: i64 = 0;
            while j < b.len() && b[j].is_ascii_digit() {
                e = e.saturating_mul(10).saturating_add((b[j] - b'0') as i64);
                if e > 1_000_000_000 {
                    e = 1_000_000_000;
                }
                j += 1;
            }
            dexp = if eneg { -e } else { e };
            end = j;
        }
    }

    let nfrac = frac_digits.len() as i64;
    let mut digits = int_digits;
    digits.extend_from_slice(&frac_digits);
    // strip leading zeros
    let first_nz = digits.iter().position(|&d| d != 0);
    let (bits, erange) = match first_nz {
        None => (0u32, false), // exact zero, never ERANGE (e.g. "0e99999999999999999999")
        Some(p) => {
            let sig = &digits[p..];
            let e10 = dexp.saturating_sub(nfrac);
            let mag = e10.saturating_add(sig.len() as i64); // 10^(mag-1) <= value < 10^mag
