                (0x7f80_0000u32, true) // definitely > FLT_MAX
            } else if mag < -46 {
                (0u32, true) // definitely < 2^-150/2 -> rounds to 0, inexact
            } else {
                let mut s = String::with_capacity(sig.len() + 24);
                for &d in sig {
                    s.push((b'0' + d) as char);
                }
                s.push('e');
                s.push_str(&e10.to_string());
