                    (0x7f80_0000u32, true)
                } else {
                    let vb = v.to_bits();
                    if vb < 0x0080_0000 {
                        // tiny (correctly-rounded |v| < 2^-126  <=>  glibc's is_tiny,
                        // because the 24-bit-rounding carry threshold 2^-126 - 2^-151
                        // is exactly the f32 rounding midpoint below 2^-126)
                        let exact = dec_is_exact(sig, e10, vb);
                        (vb, !exact)
                    } else {
                        (vb, false)
                    }
                }
            }
        }
    };
