}

/// Is `sig * 10^e10` exactly equal to `k * 2^-149` (k = subnormal bit pattern)?
fn dec_is_exact(sig: &[u8], e10: i64, k: u32) -> bool {
    if k == 0 {
        return false; // sig is nonzero here
    }
    // drop trailing zeros
    let mut n = sig.len();
    let mut e = e10;
    while n > 1 && sig[n - 1] == 0 {
        n -= 1;
        e += 1;
    }
    if e >= 0 {
        return false; // integer >= 1, cannot be < 2^-126
    }
    let m = (-e) as u64;
    // an exact k*2^-149 (k < 2^24) has at most ~111 significant decimal digits
    if n > 200 || m > 500 {
        return false;
    }
    let mut a = big_from_digits(&sig[..n]);
    big_shl(&mut a, 149);
    let mut c = vec![k];
    for _ in 0..m {
        big_mul_small(&mut c, 10);
    }
    big_cmp(&a, &c) == Ordering::Equal
}

// --- minimal big unsigned integer (little-endian u32 limbs) ---------------

fn big_from_digits(d: &[u8]) -> Vec<u32> {
    let mut v: Vec<u32> = vec![0];
    for &c in d {
        big_mul_small(&mut v, 10);
        big_add_small(&mut v, c as u32);
    }
    big_trim(&mut v);
    v
}

fn big_trim(v: &mut Vec<u32>) {
    while v.len() > 1 && *v.last().unwrap() == 0 {
        v.pop();
    }
}

fn big_mul_small(v: &mut Vec<u32>, m: u32) {
    let mut carry: u64 = 0;
    for limb in v.iter_mut() {
        let cur = *limb as u64 * m as u64 + carry;
        *limb = cur as u32;
        carry = cur >> 32;
    }
    while carry != 0 {
        v.push(carry as u32);
        carry >>= 32;
    }
}

fn big_add_small(v: &mut Vec<u32>, a: u32) {
    let mut carry = a as u64;
    for limb in v.iter_mut() {
        if carry == 0 {
            break;
        }
        let cur = *limb as u64 + carry;
        *limb = cur as u32;
        carry = cur >> 32;
    }
    if carry != 0 {
        v.push(carry as u32);
    }
}

fn big_shl(v: &mut Vec<u32>, bits: u32) {
    let words = (bits / 32) as usize;
    let rem = bits % 32;
    if rem != 0 {
        let mut carry = 0u32;
        for limb in v.iter_mut() {
            let cur = ((*limb as u64) << rem) | carry as u64;
            *limb = cur as u32;
            carry = (cur >> 32) as u32;
        }
        if carry != 0 {
            v.push(carry);
        }
    }
    if words != 0 {
        let mut nv = vec![0u32; words];
        nv.extend_from_slice(v);
        *v = nv;
    }
    big_trim(v);
}

fn big_cmp(a: &[u32], b: &[u32]) -> Ordering {
    let la = a.iter().rposition(|&x| x != 0).map_or(0, |p| p + 1);
    let lb = b.iter().rposition(|&x| x != 0).map_or(0, |p| p + 1);
    if la != lb {
        return la.cmp(&lb);
    }
    for i in (0..la).rev() {
        if a[i] != b[i] {
            return a[i].cmp(&b[i]);
        }
    }
    Ordering::Equal
}
