use std::io::{self, Read, Write, BufWriter};

fn unhex(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut v = Vec::with_capacity(b.len()/2);
    let mut i = 0;
    while i + 1 < b.len() {
        let h = |c: u8| -> u8 { match c { b'0'..=b'9' => c-b'0', b'a'..=b'f' => c-b'a'+10, b'A'..=b'F' => c-b'A'+10, _ => 0 } };
        v.push(h(b[i])*16 + h(b[i+1]));
        i += 2;
    }
    v
}

fn main() {
    let mut inp = String::new();
    io::stdin().read_to_string(&mut inp).unwrap();
    let out = io::stdout();
    let mut w = BufWriter::new(out.lock());
    for line in inp.lines() {
        if line.is_empty() { writeln!(w, "{}", describe(&[])).unwrap(); continue; }
        let bytes = unhex(line);
        writeln!(w, "{}", describe(&bytes)).unwrap();
    }
}

fn describe(b: &[u8]) -> String {
    match stof::stof_bytes(b) {
        Ok(v) => format!("OK {:08x}", v.to_bits()),
        Err(stof::StofErr::Invalid) => "INVALID 00000000".to_string(),
        Err(stof::StofErr::OutOfRange) => "RANGE 00000000".to_string(),
    }
}
