            if cmp(&lhs,&u)!=std::cmp::Ordering::Less { l=cand; found=true; break; }
        }
        assert!(found);
        // extract bits: R = S * 2^(-L+K) ... do it as: R = S scaled by 2^(shiftbase), unit = u
        // We iterate e from l down to l-40 ; represent value*2^(-l+j)
        let mut r = shl(&s_big, (-l) as u32); // r/u = value*2^(-l) in [1,2)
        let mut bits=String::new();
        let mut exact_at:i64=-1000;
        for j in 0..60 {
            if cmp(&r,&u)!=std::cmp::Ordering::Less { bits.push('1'); sub(&mut r,&u); } else { bits.push('0'); }
            if is_zero(&r) { exact_at = l - j; break; }
            r=shl(&r,1);
        }
        println!("L={} bits={} terminates_at_2^{} ", l, bits, exact_at);
    }
}
